// varsayılan zemin: hiç seçilmediyse efekt renkleri (Meditasyon). Koyu seçildiyse { mode: 'dark' } saklanır
const LP_DEFAULT_BG_SEL = { mode: 'fx', fx: 'zen' };
const LP_DEFAULT_BG = lpBgCss(LP_DEFAULT_BG_SEL);
