const lpErKpi = (lab, big, sub, cls) => '<div class="exst exk"><span>' + esc(lab) + '</span><b>' + esc(big) + '</b><span' + (cls ? ' class="' + cls + '"' : '') + '>' + esc(sub) + '</span></div>';
