    '<div class="exrg"><div class="exbox"><h4>' + esc(lpErT(lang, 'topM')) + '</h4>' + lpErTop(h, M, D, lang) + '</div><div class="exbox"><h4>' + esc(lpErT(lang, 'wk')) + ' <i>' + esc(lpErT(lang, 'perDay')) + '</i></h4>' + wk + (ins ? '<div class="exins">' + ins + '</div>' : '') + '</div></div>';
