    let yy = H - pb; M.cats.forEach((cc) => { const v = r.c[cc.id] || 0, hh = v / mx * (H - pb - 12); if (hh <= 0) return; yy -= hh; s += '<rect x="' + (X + 1).toFixed(1) + '" y="' + yy.toFixed(1) + '" width="' + bw.toFixed(1) + '" height="' + hh.toFixed(1) + '" fill="' + cc.color + '"/>'; });
