// giriş yapmış kişinin telefonları: kişinin (person) takip ettiği mobil uygulama cihazları; bulunamazsa evde tek telefon varsa o
function lhdPhones(hass) {
  const svc = (hass && hass.services && hass.services.notify) || {}, out = [];
  const add = (sv, name) => { if (svc[sv] && !out.some((x) => x.svc === sv)) out.push({ svc: sv, name: name }); };
  const uid = hass && hass.user && hass.user.id, st = (hass && hass.states) || {}, ents = (hass && hass.entities) || {}, devs = (hass && hass.devices) || {};
  Object.keys(st).forEach((eid) => {
    if (eid.indexOf('person.') !== 0 || !uid || st[eid].attributes.user_id !== uid) return;
    (st[eid].attributes.device_trackers || []).forEach((tid) => {
      const en = ents[tid]; if (!en || en.platform !== 'mobile_app' || !en.device_id) return;
      const dv = devs[en.device_id]; if (!dv) return;
      add('mobile_app_' + lhdMaSlug(dv.name), dv.name_by_user || dv.name);
    });
  });
  if (!out.length) { const all = Object.keys(svc).filter((k) => k.indexOf('mobile_app_') === 0); if (all.length === 1) add(all[0], all[0].slice(11)); }
  return out;
}
function lhdPickSend(hass, phone, item, store, lang) {
  const url = lhdHttps((item.buy || {})[store]);
  const nm = (LHD_PICK_STORES.filter((x) => x[0] === store)[0] || ['', ''])[1];
  return hass.callService('notify', phone.svc, {
    title: item.name,
    message: lang === 'tr' ? nm + ' uygulamasında açmak için dokun' : 'Tap to open in the ' + nm + ' app',
    data: { url: url, clickAction: url, tag: 'lhd-pick' }
  });
}
