        '<div class="tfli"><div class="k"><b>' + t('enRowSktt') + '</b><span>' + t('enRowSkttT') + '</span></div><div class="v">' + num('energy.sktt_price', en.sktt_price, '0.01', cur, '~7') + '</div></div></div>';
