    const gName = (g) => (G === 'room' ? (g ? this._enAreaN(g) : this._t('enDvNoRoom')) : (g ? catN(g) : this._t('enNoCat')));
    const GR = {}; top.forEach((k) => { const g = gKey(k); (GR[g] = GR[g] || []).push(k); });
