      (inP.length ? '<optgroup label="' + esc(this._t('enPick1N', { n: inP.length })) + '">' + inP.map(o).join('') + '</optgroup>' : '') +
      (rest.length ? '<optgroup label="' + esc(this._t('enPickOther')) + '">' + rest.map(o).join('') + '</optgroup>' : '') + '</select></div>';
