    const vo = same.filter((id) => S[id].attributes.device_class === 'voltage' || String(S[id].attributes.unit_of_measurement || '') === 'V').sort((a, b) => score(b) - score(a))[0] || '';
    return { power: pid, energy: en, out: ex, volt: vo };
