    if (!P) return h + '<div class="acts"><button class="btn pri" data-a="enimpscan"' + (this._enBusy ? ' disabled' : '') + '><ha-icon class="s16" icon="mdi:magnify"></ha-icon>' + t('enImpScan') + '</button></div>';
