    const tb0 = this._curTab(this._work()), ps = this._phEd() && s.phone && s.phone.style && s.phone.style.bg;
    box.style.background = (!ps && lpTabBg(tb0)) || lpBgOf(this._phEd() ? lpPhoneMerge(s) : s);   // odaya özel zemin önizlemede de
