    const sc = LHD_SCREENS.filter((x) => x[0] === this._screenKey())[0];
    const cs = sc[0] === 'custom' ? lhdCustomScr() : null, sw = cs ? cs[0] : sc[1] || window.innerWidth, sh = cs ? cs[1] : sc[2] || window.innerHeight;
    const ph = this._scrPh(sc[0]);
