          let ref = null;
          for (let i = 0; i < rest.length; i++) { const r = rest[i].getBoundingClientRect(); if (pos < (horiz ? r.left + r.width / 2 : r.top + r.height / 2)) { ref = rest[i]; break; } }
          if (!ref) { const last = rest[rest.length - 1]; ref = last ? last.nextSibling : null; }
